// The model answers in Markdown whatever the prompt asks for, so the widget
// renders a small subset of it rather than showing raw asterisks and bracket
// syntax to a recruiter.
//
// Deliberately not a Markdown library: this handles the four things the model
// actually produces — paragraphs, bullets, bold, inline code and links — in a
// few lines that can be read end to end. Anything else is shown as plain text.
//
// Links are generated by a language model, so they are treated as untrusted:
// only http(s) and same-site paths render as links, everything else degrades
// to its label. Without that check an invented `javascript:` URL would become
// a clickable script.

import { Fragment, type ReactNode } from "react";

export function renderAnswer(text: string): ReactNode {
  const blocks = text.trim().split(/\n{2,}/);

  return blocks.map((block, blockIndex) => {
    const lines = block.split("\n");
    const isList = lines.every((line) => /^\s*[*-]\s+/.test(line));

    if (isList) {
      return (
        <ul className="ml-4 list-disc space-y-1" key={blockIndex}>
          {lines.map((line, lineIndex) => (
            <li key={lineIndex}>{renderInline(line.replace(/^\s*[*-]\s+/, ""))}</li>
          ))}
        </ul>
      );
    }

    return <p key={blockIndex}>{renderInline(block)}</p>;
  });
}

/** Handles **bold**, `code` and [label](url), in one pass. */
function renderInline(text: string): ReactNode[] {
  const pattern = /\*\*(.+?)\*\*|`(.+?)`|\[(.+?)\]\(([^)]+)\)/g;
  const nodes: ReactNode[] = [];
  let lastIndex = 0;
  let match: RegExpExecArray | null;
  let key = 0;

  while ((match = pattern.exec(text)) !== null) {
    if (match.index > lastIndex) {
      nodes.push(
        <Fragment key={key++}>{text.slice(lastIndex, match.index)}</Fragment>
      );
    }

    const [, bold, code, label, href] = match;
    if (bold !== undefined) {
      nodes.push(<strong key={key++}>{bold}</strong>);
    } else if (code !== undefined) {
      nodes.push(
        <code className="break-all text-xs" key={key++}>
          {code}
        </code>
      );
    } else if (label !== undefined && href !== undefined) {
      nodes.push(
        isSafeHref(href) ? (
          <a className="text-accent hover:underline" href={href} key={key++}>
            {label}
          </a>
        ) : (
          // An unsafe or odd URL loses its link but keeps its text: the
          // sentence still reads, nothing clickable is created.
          <Fragment key={key++}>{label}</Fragment>
        )
      );
    }

    lastIndex = match.index + match[0].length;
  }

  if (lastIndex < text.length) {
    nodes.push(<Fragment key={key++}>{text.slice(lastIndex)}</Fragment>);
  }
  return nodes;
}

/** Absolute http(s), or a path on this site. Nothing else. */
export function isSafeHref(href: string): boolean {
  const value = href.trim();
  if (value.startsWith("/")) return !value.startsWith("//");
  return /^https?:\/\//i.test(value);
}
